import docx
d = docx.Document("offer_letter_filled.docx")
def texts(doc):
    out=[]
    for p in doc.paragraphs: out.append(p.text)
    for t in doc.tables:
        for r in t.rows:
            for c in r.cells:
                for p in c.paragraphs: out.append(p.text)
    for s in doc.sections:
        for hf in (s.header,s.footer,s.first_page_header,s.first_page_footer):
            for p in hf.paragraphs: out.append(p.text)
    return out
all_text="\n".join(texts(d))
print(all_text)
print("---CHECKS---")
print("has {{ :", "{{" in all_text)
print("RELOCATION mention:", "elocat" in all_text.lower())
print("Nóra present:", "Nóra Singh" in all_text)
EOF
